<script>
  import Icon from './Icon.svelte';
  import { iso, prettyDate } from './data.js';
  import { visiblePatients, visibleSessions, visibleFollowups, roleConfig, assignedInquiries, assignedDeskInquiries, assignedInvoices, assignedDeskSessions } from './roles.js';

  export let role;
  export let data;
  export let staff;
  export let onNavigate;
  export let onCreate;
  export let onCare;
  export let onPayment;
  export let onOutcome;

  $: patients = visiblePatients(role, data.patients, staff).filter(patient => patient.status !== 'Archived');
  $: sessions = visibleSessions(role, data.sessions, staff).filter(session => session.date === iso(0)).sort((a, b) => a.time.localeCompare(b.time));
  $: followups = visibleFollowups(role, data.followups, staff).filter(item => item.status !== 'Completed' && item.due <= iso(0) && (role !== 'Coordinator' || item.owner === staff.assignment));
  $: myInquiries = assignedInquiries(data, staff);
  $: deskInquiries = assignedDeskInquiries(data, staff);
  $: openInquiries = myInquiries.filter(item => item.stage !== 'Arrival planned');
  $: newInquiries = deskInquiries.filter(item => item.stage === 'New inquiry');
  $: arrivals = deskInquiries.filter(item => item.stage === 'Arrival planned');
  $: documentQueue = myInquiries.filter(item => !item.documents && item.stage === 'Intake review');
  $: readyBeds = data.rooms.filter(room => room.status === 'Ready').flatMap(room => room.beds).filter(bed => !bed).length;
  $: unpaid = assignedInvoices(data, staff).filter(item => !['Paid','Void'].includes(item.status));
  $: deskSessions = assignedDeskSessions(data, staff).filter(item => item.date === iso(0)).sort((a,b) => a.time.localeCompare(b.time));
  $: overdue = unpaid.filter(item => item.due < iso(0));
  $: openBalance = unpaid.reduce((sum, item) => sum + Math.max(0, item.amount - (Number(item.paid) || 0)), 0);
  $: approvalCount = (data.finance?.expenses || []).filter(item => item.status === 'Pending approval').length;
  $: unmatchedBankCount = (data.finance?.bankEntries || []).filter(item => !item.matchedJournalId).length;
</script>

<div class="role-home" class:coordinator={role==='Coordinator'} class:therapist={role==='Therapist'} class:finance={role==='Finance'} class:reception={role==='Reception'}>
  <div class="page-intro"><div><div class="eyebrow">{staff.name} / {roleConfig[role].title}</div><h1 class="page-title">{role === 'Coordinator' ? 'Keep every handoff ' : role === 'Therapist' ? 'Your care day, ' : role === 'Finance' ? 'Clarity in every ' : 'A thoughtful first '}<span class="serif">{role === 'Coordinator' ? 'moving.' : role === 'Therapist' ? 'in focus.' : role === 'Finance' ? 'balance.' : 'welcome.'}</span></h1><p class="page-desc">{role === 'Coordinator' ? 'Admissions, placements and follow-through in one working view.' : role === 'Therapist' ? 'Your assigned patients, sessions and follow-ups for today.' : role === 'Finance' ? 'Invoices, payments and outstanding items without clinical notes.' : 'The inquiries, arrivals and practical details at the front desk.'}</p></div><span class="role-home-badge"><Icon name={role === 'Coordinator' ? 'users' : role === 'Therapist' ? 'heart' : role === 'Finance' ? 'wallet' : 'inbox'} size={16}/>{staff.shortName}'s workspace</span></div>
  <section class="role-hero"><div><div class="hero-kicker">TODAY AT CEDAR · {staff.name.toUpperCase()}</div><h2>{role === 'Coordinator' ? 'The next step is easier to see.' : role === 'Therapist' ? 'More attention for the people in your care.' : role === 'Finance' ? 'A clear ledger supports a calmer day.' : 'Every arrival begins with good coordination.'}</h2><p>{role === 'Coordinator' ? 'Review open intake files, planned arrivals and follow-ups before the day moves on.' : role === 'Therapist' ? 'See your caseload and schedule together, then close the loop on assigned contacts.' : role === 'Finance' ? 'See what is due, record a payment and keep financial work in its own space.' : 'Capture the first inquiry, find the next intake appointment and check room readiness.'}</p><button class="hero-cta" on:click={() => role === 'Coordinator' ? onNavigate('admissions') : role === 'Therapist' ? onNavigate('patients') : role === 'Finance' ? onNavigate('billing') : onCreate('inquiry')}>{role === 'Coordinator' ? 'Open intake pipeline' : role === 'Therapist' ? 'Open my patients' : role === 'Finance' ? 'Open invoice ledger' : 'Add an inquiry'} <Icon name="arrow" size={14}/></button></div><div class="role-hero-art"><Icon name={role === 'Coordinator' ? 'leaf' : role === 'Therapist' ? 'heart' : role === 'Finance' ? 'chart' : 'bed'} size={100} stroke={1}/></div></section>

  {#if role === 'Coordinator'}
    <div class="role-kpis"><button on:click={() => onNavigate('admissions')}><span>Intake files to review</span><strong>{documentQueue.length}</strong><small>Documents need attention</small></button><button on:click={() => onNavigate('admissions')}><span>Active inquiries</span><strong>{openInquiries.length}</strong><small>Each with a next action</small></button><button on:click={() => onNavigate('rooms')}><span>Beds ready</span><strong>{readyBeds}</strong><small>Staff-confirmed placement</small></button><button on:click={() => onNavigate('aftercare')}><span>Follow-ups due</span><strong>{followups.length}</strong><small>Assigned to {staff.shortName}</small></button></div>
    <div class="role-columns"><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">Admissions needing a handoff</h2><p class="panel-sub">The work that moves someone closer to care</p></div><button class="text-link" on:click={() => onNavigate('admissions')}>Open pipeline →</button></div><div class="role-list">{#each [...documentQueue, ...myInquiries].filter((item,index,list) => list.findIndex(other => other.id === item.id) === index).slice(0,4) as item}<button on:click={() => onNavigate('admissions')}><span class="role-list-icon"><Icon name="inbox" size={16}/></span><span><strong>{item.id} · {item.name}</strong><small>{item.next} · {item.owner}</small></span><Icon name="chevron" size={14}/></button>{:else}<div class="role-empty">No intake handoffs need review.</div>{/each}</div></section><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">Today’s follow-through</h2><p class="panel-sub">Assigned contacts and next actions</p></div><button class="text-link" on:click={() => onNavigate('aftercare')}>Aftercare →</button></div><div class="role-list">{#each followups.slice(0,4) as item}<button on:click={() => onNavigate('aftercare')}><span class="role-list-icon"><Icon name="heart" size={16}/></span><span><strong>{item.patient} · {item.action}</strong><small>{item.owner} · {item.time}</small></span><Icon name="chevron" size={14}/></button>{:else}<div class="role-empty">No follow-ups are due today.</div>{/each}</div></section></div>
    <div class="role-quick"><button on:click={() => onNavigate('handoffs')}><Icon name="check" size={16}/> Handoff queue</button><button on:click={() => onCreate('inquiry')}><Icon name="plus" size={16}/> New inquiry</button><button on:click={() => onCreate('followup')}><Icon name="heart" size={16}/> Assign follow-up</button><button on:click={() => onNavigate('schedule')}><Icon name="calendar" size={16}/> Team schedule</button><button on:click={() => onNavigate('reports')}><Icon name="chart" size={16}/> Center reports</button><button on:click={() => onNavigate('assist')}><Icon name="sparkle" size={16}/> Investigate trends</button></div>
  {:else if role === 'Therapist'}
    <div class="role-kpis"><button on:click={() => onNavigate('patients')}><span>My patients</span><strong>{patients.length}</strong><small>Assigned to {staff.shortName}</small></button><button on:click={() => onNavigate('schedule')}><span>My sessions today</span><strong>{sessions.length}</strong><small>Current schedule</small></button><button on:click={() => onNavigate('aftercare')}><span>My follow-ups due</span><strong>{followups.length}</strong><small>Record an outcome</small></button></div>
    <div class="role-columns"><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">My caseload</h2><p class="panel-sub">Care tasks visible to your role</p></div><button class="text-link" on:click={() => onNavigate('patients')}>All patients →</button></div><div class="role-list">{#each patients.slice(0,5) as patient}<button on:click={() => onCare(patient)}><span class="role-list-icon"><Icon name="users" size={16}/></span><span><strong>{patient.name}</strong><small>{patient.care}</small></span><Icon name="chevron" size={14}/></button>{/each}</div></section><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">Today’s sessions</h2><p class="panel-sub">Your own appointments</p></div><button class="text-link" on:click={() => onNavigate('schedule')}>My calendar →</button></div><div class="role-list">{#each sessions.slice(0,5) as item}<button on:click={() => onNavigate('schedule')}><span class="role-list-time">{item.time}</span><span><strong>{item.title}</strong><small>{item.meta}</small></span><Icon name="chevron" size={14}/></button>{:else}<div class="role-empty">No sessions scheduled today.</div>{/each}</div></section></div>
    {#if followups.length}<section class="panel role-panel role-full"><div class="panel-head"><div><h2 class="panel-title">Contacts to close today</h2><p class="panel-sub">Only your assigned follow-ups</p></div></div><div class="role-list">{#each followups as item}<div class="role-action-row"><span><strong>{item.patient} · {item.action}</strong><small>{prettyDate(item.due)} at {item.time} · {item.consent}</small></span><button class="btn btn-soft btn-tiny" on:click={() => onOutcome(item.id)}>Record outcome</button></div>{/each}</div></section>{/if}
    <div class="role-quick"><button on:click={() => onNavigate('careplans')}><Icon name="heart" size={16}/> Care plans</button><button on:click={() => onNavigate('clinicalreports')}><Icon name="inbox" size={16}/> Clinical reports</button><button on:click={() => onNavigate('patients')}><Icon name="users" size={16}/> My patients</button></div>
  {:else if role === 'Finance'}
    <div class="role-kpis"><button on:click={() => onNavigate('payments')}><span>Open balance</span><strong>${openBalance.toLocaleString()}</strong><small>Assigned to {staff.shortName}</small></button><button on:click={() => onNavigate('payments')}><span>Past due</span><strong>{overdue.length}</strong><small>Needs payment review</small></button><button on:click={() => onNavigate('expenses')}><span>Expenses to approve</span><strong>{approvalCount}</strong><small>Before ledger posting</small></button><button on:click={() => onNavigate('reconciliation')}><span>Bank lines to match</span><strong>{unmatchedBankCount}</strong><small>Statement review</small></button></div>
    <div class="role-columns"><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">Payment worklist</h2><p class="panel-sub">Balances ready for follow-up</p></div><button class="text-link" on:click={() => onNavigate('payments')}>Receipts & collections →</button></div><div class="role-list">{#each unpaid.slice(0,5) as item}<div class="role-action-row"><span><strong>{item.id} · {item.payer}</strong><small>{item.patient} · ${Math.max(0,item.amount-(Number(item.paid)||0)).toLocaleString()} open · due {prettyDate(item.due)}</small></span><button class="btn btn-soft btn-tiny" on:click={() => onPayment(item)}>Payment</button></div>{:else}<div class="role-empty">No open balances.</div>{/each}</div></section><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">Close the books</h2><p class="panel-sub">The next accounting actions</p></div><button class="text-link" on:click={() => onNavigate('ledger')}>General ledger →</button></div><div class="role-list"><button on:click={() => onNavigate('expenses')}><span class="role-list-icon"><Icon name="inbox" size={16}/></span><span><strong>{approvalCount} supplier bills to approve</strong><small>Review references before posting</small></span><Icon name="chevron" size={14}/></button><button on:click={() => onNavigate('reconciliation')}><span class="role-list-icon"><Icon name="check" size={16}/></span><span><strong>{unmatchedBankCount} statement lines unmatched</strong><small>Compare against book cash entries</small></span><Icon name="chevron" size={14}/></button><button on:click={() => onNavigate('payers')}><span class="role-list-icon"><Icon name="users" size={16}/></span><span><strong>Payer accounts</strong><small>See billed, received and open funding</small></span><Icon name="chevron" size={14}/></button></div></section></div>
    <div class="role-quick"><button on:click={() => onCreate('invoice')}><Icon name="plus" size={16}/> New invoice</button><button on:click={() => onNavigate('payments')}><Icon name="wallet" size={16}/> Payments</button><button on:click={() => onNavigate('expenses')}><Icon name="inbox" size={16}/> Expenses</button><button on:click={() => onNavigate('ledger')}><Icon name="chart" size={16}/> Ledger</button><button on:click={() => onNavigate('reports')}><Icon name="chart" size={16}/> Financial reports</button></div>
  {:else if role === 'Reception'}
    <div class="role-kpis"><button on:click={() => onNavigate('admissions')}><span>New inquiries</span><strong>{newInquiries.length}</strong><small>First contact to arrange</small></button><button on:click={() => onNavigate('admissions')}><span>Arrivals planned</span><strong>{arrivals.length}</strong><small>Welcome preparation</small></button><button on:click={() => onNavigate('rooms')}><span>Beds ready</span><strong>{readyBeds}</strong><small>Read-only capacity view</small></button><button on:click={() => onNavigate('schedule')}><span>Desk schedule today</span><strong>{deskSessions.length}</strong><small>Assigned desk events</small></button></div>
    <div class="role-columns"><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">First contacts</h2><p class="panel-sub">The next practical step for each inquiry</p></div><button class="text-link" on:click={() => onNavigate('admissions')}>Admissions →</button></div><div class="role-list">{#each newInquiries.slice(0,5) as item}<button on:click={() => onNavigate('admissions')}><span class="role-list-icon"><Icon name="inbox" size={16}/></span><span><strong>{item.id} · {item.name}</strong><small>{item.source} · {item.next}</small></span><Icon name="chevron" size={14}/></button>{:else}<div class="role-empty">No new inquiries waiting.</div>{/each}</div></section><section class="panel role-panel"><div class="panel-head"><div><h2 class="panel-title">Arrivals to prepare</h2><p class="panel-sub">Welcome details and room visibility</p></div><button class="text-link" on:click={() => onNavigate('rooms')}>Room board →</button></div><div class="role-list">{#each arrivals.slice(0,5) as item}<button on:click={() => onNavigate('admissions')}><span class="role-list-icon"><Icon name="calendar" size={16}/></span><span><strong>{item.id} · {item.name}</strong><small>{prettyDate(item.date)} · {item.next}</small></span><Icon name="chevron" size={14}/></button>{:else}<div class="role-empty">No arrivals planned.</div>{/each}</div></section></div>
    <div class="role-quick"><button on:click={() => onNavigate('arrivals')}><Icon name="calendar" size={16}/> Planned arrivals</button><button on:click={() => onCreate('inquiry')}><Icon name="plus" size={16}/> Capture inquiry</button><button on:click={() => onCreate('session')}><Icon name="calendar" size={16}/> Schedule intake</button><button on:click={() => onNavigate('rooms')}><Icon name="bed" size={16}/> Check room readiness</button></div>
  {/if}
</div>
